-- The public web-report reader used to render `text_content` directly. That
-- column is the readable source extract, so the reading panel was republishing
-- the publisher's wording verbatim. Keep the extract for attribution, search
-- and the data export, but give the reading surface a separate, cached,
-- source-grounded digest generated by the `ice-source-refine` Supabase Edge
-- Function.
--
-- The digest is nullable on purpose: existing rows predate the endpoint, and
-- the reader generates (and stores) one on first open. It is never a fallback
-- for the raw extract; a missing digest means the reader shows the original
-- source link, not copied prose.
alter table public.ice_source_reports
  add column if not exists refined_text text,
  add column if not exists refined_at timestamptz;

alter table public.ice_source_reports
  drop constraint if exists ice_source_reports_refined_text_check;

alter table public.ice_source_reports
  add constraint ice_source_reports_refined_text_check
  check (
    refined_text is null
    or length(refined_text) between 120 and 5000
  );

comment on column public.ice_source_reports.refined_text is
  'AI-generated, source-grounded digest shown by the public reading panel. '
  'It paraphrases the source; it is not a replacement for the attributed '
  'text_content extract or the original source URL.';
comment on column public.ice_source_reports.refined_at is
  'When refined_text was generated. Null until the digest is requested.';

-- The public read routes use the service role, but granting these columns
-- keeps a future anon/authenticated projection from failing at schema-cache
-- selection time. The raw extract remains the attributed source record.
grant select (refined_text, refined_at) on table public.ice_source_reports
  to anon, authenticated;
